mapper.select:
/* AttdCloseMapper.selectCloseRow */
SELECT
      A.CLOSE_YM                                          AS closeYm
    , A.CLOSE_STATUS                                      AS closeStatus
    , DATE_FORMAT(A.CLOSE_DTIME, '%Y-%m-%dT%H:%i:%s')     AS closeDtime
    , A.CLOSE_USER_CD                                     AS closeUserCd
    , DATE_FORMAT(A.UNCLOSE_DTIME, '%Y-%m-%dT%H:%i:%s')   AS uncloseDtime
    , A.UNCLOSE_USER_CD                                   AS uncloseUserCd
    , A.CLOSE_DESC                                        AS closeDesc
  FROM TB_ATTD_CLOSE A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.SITE_CD  = #{siteCd}
   AND A.NODE_CD  = #{nodeCd}
   AND A.CLOSE_YM = #{closeYm}
 LIMIT 1

/* AttdCloseMapper.countPendingReq */
SELECT COUNT(*) FROM TB_USER_ATTD_REQ A WHERE A.CMPNY_CD = #{cmpnyCd} AND A.SITE_CD = #{siteCd} AND LEFT(A.WORK_YMD, 6) = #{closeYm} AND A.REQ_STATUS = '01' AND A.DEL_YN = 'N' AND A.REQ_TYPE NOT IN ('03', '04')
WITH RECURSIVE node_tree AS ( SELECT N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{cmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL SELECT C.NODE_CD FROM TB_SITE_NODE C JOIN node_tree P ON C.CMPNY_CD = #{cmpnyCd} AND C.SITE_CD = #{siteCd} AND C.PARENT_NODE_CD = P.NODE_CD
) SELECT COUNT(*) FROM TB_USER_ATTD_REQ A WHERE A.CMPNY_CD = #{cmpnyCd} AND A.SITE_CD = #{siteCd}
AND COALESCE(NULLIF(A.NODE_CD, ''), ( SELECT U.NODE_CD FROM TB_USER U WHERE U.CMPNY_CD = A.CMPNY_CD AND U.SITE_CD = A.SITE_CD AND U.USER_CD = A.USER_CD LIMIT 1 )) IN (SELECT NODE_CD FROM node_tree) AND LEFT(A.WORK_YMD, 6) = #{closeYm} AND A.REQ_STATUS = '01' AND A.DEL_YN = 'N' AND A.REQ_TYPE NOT IN ('03', '04')

/* AttdCloseMapper.countUnapprovedOt */
SELECT COUNT(*) FROM TB_USER_ATTD_REQ A WHERE A.CMPNY_CD = #{cmpnyCd} AND A.SITE_CD = #{siteCd} AND LEFT(A.WORK_YMD, 6) = #{closeYm} AND A.REQ_STATUS = '01' AND A.DEL_YN = 'N' AND A.REQ_TYPE IN ('03', '04')
WITH RECURSIVE node_tree AS ( SELECT N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{cmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL SELECT C.NODE_CD FROM TB_SITE_NODE C JOIN node_tree P ON C.CMPNY_CD = #{cmpnyCd} AND C.SITE_CD = #{siteCd} AND C.PARENT_NODE_CD = P.NODE_CD
) SELECT COUNT(*) FROM TB_USER_ATTD_REQ A WHERE A.CMPNY_CD = #{cmpnyCd} AND A.SITE_CD = #{siteCd}
AND COALESCE(NULLIF(A.NODE_CD, ''), ( SELECT U.NODE_CD FROM TB_USER U WHERE U.CMPNY_CD = A.CMPNY_CD AND U.SITE_CD = A.SITE_CD AND U.USER_CD = A.USER_CD LIMIT 1 )) IN (SELECT NODE_CD FROM node_tree) AND LEFT(A.WORK_YMD, 6) = #{closeYm} AND A.REQ_STATUS = '01' AND A.DEL_YN = 'N' AND A.REQ_TYPE IN ('03', '04')

/* AttdCloseMapper.countPendingLeaveChange */


    SELECT COUNT(*)
      FROM TB_LEAVE_CHANGE_REQUEST R
      INNER JOIN TB_USER_LEAVE_USE LU
              ON LU.CMPNY_CD = R.CMPNY_CD
             AND LU.LEAVE_ID = R.TARGET_LEAVE_ID
     WHERE R.CMPNY_CD   = #{cmpnyCd}
       AND R.SITE_CD    = #{siteCd}
       AND R.DEL_YN     = 'N'
       AND R.REQ_STATUS IN ('REQUESTED', 'AGREED')
       AND ( LEFT(LU.START_DATE, 6) = #{closeYm}
          OR LEFT(R.MOVE_TARGET_DATE, 6) = #{closeYm} )


    WITH RECURSIVE node_tree AS (
        SELECT N.NODE_CD
          FROM TB_SITE_NODE N
         WHERE N.CMPNY_CD = #{cmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}

        UNION ALL
        SELECT C.NODE_CD
          FROM TB_SITE_NODE C
          JOIN node_tree P
            ON C.CMPNY_CD = #{cmpnyCd} AND C.SITE_CD = #{siteCd} AND C.PARENT_NODE_CD = P.NODE_CD

    )
    SELECT COUNT(*)
      FROM TB_LEAVE_CHANGE_REQUEST R
      INNER JOIN TB_USER_LEAVE_USE LU
              ON LU.CMPNY_CD = R.CMPNY_CD
             AND LU.LEAVE_ID = R.TARGET_LEAVE_ID
     WHERE R.CMPNY_CD   = #{cmpnyCd}
       AND R.SITE_CD    = #{siteCd}
       AND R.DEL_YN     = 'N'
       AND R.REQ_STATUS IN ('REQUESTED', 'AGREED')
       AND ( LEFT(LU.START_DATE, 6) = #{closeYm}
          OR LEFT(R.MOVE_TARGET_DATE, 6) = #{closeYm} )
       AND R.TARGET_USER_CD IN (
               SELECT NU.USER_CD
                 FROM TB_USER NU
                WHERE NU.CMPNY_CD = #{cmpnyCd}
                  AND NU.SITE_CD  = #{siteCd}
                  AND NU.NODE_CD  IN (SELECT NODE_CD FROM node_tree)
           )

/* AttdCloseMapper.countGpsUnconfirmed */
SELECT COUNT(*) FROM TB_USER_ATTD_GPS A WHERE A.CMPNY_CD = #{cmpnyCd} AND A.SITE_CD = #{siteCd} AND LEFT(A.API_CALL_DATE, 6) = #{closeYm} AND A.IS_MOCKED = 'Y' AND NOT EXISTS ( SELECT 1 FROM TB_USER_ATTD_REQ R WHERE R.CMPNY_CD = A.CMPNY_CD AND R.SITE_CD = A.SITE_CD AND R.USER_CD = A.USER_CD AND R.WORK_YMD = A.API_CALL_DATE AND R.REQ_TYPE IN ('01','02') AND R.REQ_STATUS = '02' AND R.DEL_YN = 'N' )
WITH RECURSIVE node_tree AS ( SELECT N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{cmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL SELECT C.NODE_CD FROM TB_SITE_NODE C JOIN node_tree P ON C.CMPNY_CD = #{cmpnyCd} AND C.SITE_CD = #{siteCd} AND C.PARENT_NODE_CD = P.NODE_CD
) SELECT COUNT(*) FROM TB_USER_ATTD_GPS A JOIN TB_USER U ON U.CMPNY_CD = A.CMPNY_CD AND U.SITE_CD = A.SITE_CD AND U.USER_CD = A.USER_CD WHERE A.CMPNY_CD = #{cmpnyCd} AND A.SITE_CD = #{siteCd} AND U.NODE_CD IN (SELECT NODE_CD FROM node_tree) AND LEFT(A.API_CALL_DATE, 6) = #{closeYm} AND A.IS_MOCKED = 'Y' AND NOT EXISTS ( SELECT 1 FROM TB_USER_ATTD_REQ R WHERE R.CMPNY_CD = A.CMPNY_CD AND R.SITE_CD = A.SITE_CD AND R.USER_CD = A.USER_CD AND R.WORK_YMD = A.API_CALL_DATE AND R.REQ_TYPE IN ('01','02') AND R.REQ_STATUS = '02' AND R.DEL_YN = 'N' )

/* AttdCloseMapper.countClosed */
SELECT COUNT(*)
  FROM TB_ATTD_CLOSE A
 WHERE A.CMPNY_CD     = #{cmpnyCd}
   AND A.SITE_CD      = #{siteCd}
   AND A.NODE_CD      = #{nodeCd}
   AND A.CLOSE_YM     = #{closeYm}
   AND A.CLOSE_STATUS = 'CLOSED'

/* AttdCloseMapper.countCovering */
SELECT COUNT(*) FROM TB_ATTD_CLOSE C WHERE C.CMPNY_CD = #{cmpnyCd} AND C.SITE_CD = #{siteCd} AND C.CLOSE_YM = #{closeYm} AND C.CLOSE_STATUS = 'CLOSED' AND C.NODE_CD = '*'
WITH RECURSIVE anc AS ( SELECT N.NODE_CD, N.PARENT_NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{cmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd} UNION ALL SELECT P.NODE_CD, P.PARENT_NODE_CD FROM TB_SITE_NODE P JOIN anc A2 ON P.CMPNY_CD = #{cmpnyCd} AND P.SITE_CD = #{siteCd} AND P.NODE_CD = A2.PARENT_NODE_CD ) SELECT COUNT(*) FROM TB_ATTD_CLOSE C WHERE C.CMPNY_CD = #{cmpnyCd} AND C.SITE_CD = #{siteCd} AND C.CLOSE_YM = #{closeYm} AND C.CLOSE_STATUS = 'CLOSED' AND ( C.NODE_CD = '*' OR C.NODE_CD = #{nodeCd} OR (C.INC_SUB_YN = 'Y' AND C.NODE_CD IN (SELECT NODE_CD FROM anc WHERE NODE_CD != #{nodeCd})) )

/* AttdCloseMapper.selectNodeApprovalInfo */
SELECT
      N.SELF_ATTD_APPRV_YN   AS selfAttdApprvYn
    , N.PARENT_NODE_CD       AS parentNodeCd
    , N.MAIN_ADMIN_CD        AS mainAdminCd
    , N.SUB_ADMIN_CD         AS subAdminCd
  FROM TB_SITE_NODE N
 WHERE N.CMPNY_CD = #{cmpnyCd}
   AND N.SITE_CD  = #{siteCd}
   AND N.NODE_CD  = #{nodeCd}
 LIMIT 1

/* AttdCloseMapper.selectUserNodeCd */
SELECT U.NODE_CD
  FROM TB_USER U
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.SITE_CD  = #{siteCd}
   AND U.USER_CD  = #{userCd}
 LIMIT 1

mapper.insert:
/* AttdCloseMapper.upsertClose */
INSERT INTO TB_ATTD_CLOSE (
      CMPNY_CD
    , SITE_CD
    , NODE_CD
    , INC_SUB_YN
    , CLOSE_YM
    , CLOSE_STATUS
    , CLOSE_DTIME
    , CLOSE_USER_CD
    , CLOSE_DESC
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (
      #{cmpnyCd}
    , #{siteCd}
    , #{nodeCd}
    , #{incSubNodeYn}
    , #{closeYm}
    , 'CLOSED'
    , NOW()
    , #{userCd}
    , #{closeDesc}
    , #{userCd}
    , NOW()
    , #{userCd}
    , NOW()
) AS NEW
ON DUPLICATE KEY UPDATE
      CLOSE_STATUS  = 'CLOSED'
    , INC_SUB_YN    = NEW.INC_SUB_YN
    , CLOSE_DTIME   = NOW()
    , CLOSE_USER_CD = NEW.CLOSE_USER_CD
    , CLOSE_DESC    = NEW.CLOSE_DESC
    , UPDATE_NO     = NEW.UPDATE_NO
    , UPDATE_DATE   = NOW()

mapper.update:
/* AttdCloseMapper.updateUnclose */
UPDATE TB_ATTD_CLOSE
   SET CLOSE_STATUS    = 'OPEN'
     , UNCLOSE_DTIME   = NOW()
     , UNCLOSE_USER_CD = #{userCd}
     , CLOSE_DESC      = #{closeDesc}
     , UPDATE_NO       = #{userCd}
     , UPDATE_DATE     = NOW()
 WHERE CMPNY_CD     = #{cmpnyCd}
   AND SITE_CD      = #{siteCd}
   AND NODE_CD      = #{nodeCd}
   AND CLOSE_YM     = #{closeYm}
   AND CLOSE_STATUS = 'CLOSED'

