/* AttdCloseMapper.insertCloseHist */
INSERT INTO TB_ATTD_CLOSE_HIST (
      HIST_ID
    , CMPNY_CD
    , SITE_CD
    , NODE_CD
    , INC_SUB_YN
    , CLOSE_YM
    , ACTION_TYPE
    , ACTION_USER_CD
    , ACTION_DTIME
    , ACTION_DESC
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{histId}
    , #{cmpnyCd}
    , #{siteCd}
    , #{nodeCd}
    , #{incSubNodeYn}
    , #{closeYm}
    , #{actionType}
    , #{userCd}
    , NOW()
    , #{actionDesc}
    , #{userCd}
    , NOW()
)

mapper.select:
/* AttdCloseMapper.selectCloseHist */
SELECT
      A.HIST_ID                                          AS histId
    , A.CLOSE_YM                                         AS closeYm
    , A.ACTION_TYPE                                      AS actionType
    , A.ACTION_USER_CD                                   AS actionUserCd
    , DATE_FORMAT(A.ACTION_DTIME, '%Y-%m-%dT%H:%i:%s')   AS actionDtime
    , A.ACTION_DESC                                      AS actionDesc
  FROM TB_ATTD_CLOSE_HIST A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.SITE_CD  = #{siteCd}
   AND A.NODE_CD  = #{nodeCd}
   AND A.CLOSE_YM = #{closeYm}
 ORDER BY A.ACTION_DTIME DESC, A.HIST_ID DESC
